from typing import Dict


def get_or_create_quote(store: Dict, application_id: str, premium: float) -> float:
    """
    Idempotently get or create a quote premium for a given application.

    Behavior:
    - If a quote for `application_id` already exists in `store`, return the
      existing premium and ignore the `premium` argument.
    - If it does not exist, create it with the provided `premium`, store it,
      and return that value.

    The `store` dict is expected to be a shared, mutable data structure that
    persists between calls (e.g., at module level or injected from outside).

    Example `store` layout (convention, not enforced):
        {
            "quotes": {
                "app123": 120.50,
                "app456": 80.00,
            }
        }
    """
    if "quotes" not in store or not isinstance(store["quotes"], dict):
        # Initialize the quotes bucket if missing or malformed
        store["quotes"] = {}

    quotes = store["quotes"]

    if application_id in quotes:
        # Existing quote: return previously stored premium
        return float(quotes[application_id])

    # New quote: store and return provided premium
    quotes[application_id] = float(premium)
    return float(premium)

from datetime import datetime, timezone

def is_past_deadline(deadline: datetime, now: datetime) -> bool:
    """
    Return True if `now` is at or past `deadline`.

    Naive datetimes are assumed to be in UTC. Function works for any
    combination of naive/aware datetimes.
    """
    def to_utc(dt: datetime) -> datetime:
        if dt.tzinfo is None:
            # Treat naive datetimes as UTC
            return dt.replace(tzinfo=timezone.utc)
        # Convert aware datetimes to UTC
        return dt.astimezone(timezone.utc)

    deadline_utc = to_utc(deadline)
    now_utc = to_utc(now)

    return now_utc >= deadline_utc

from datetime import datetime, timezone

def is_past_deadline(deadline: datetime, now: datetime) -> bool:
    """
    Return True if `now >= deadline`, treating any naive datetimes as UTC.
    Works whether inputs are naive, aware, or a mix of both.
    """
    def to_utc(dt: datetime) -> datetime:
        if dt.tzinfo is None:
            # Treat naive datetime as UTC
            return dt.replace(tzinfo=timezone.utc)
        # Convert aware datetime to UTC
        return dt.astimezone(timezone.utc)

    deadline_utc = to_utc(deadline)
    now_utc = to_utc(now)
    return now_utc >= deadline_utc
